import base64, os, subprocess, tarfile, io
print("🚀 Deploying Full Ling Petshop Store to VPS...")
b64_data = """"""
os.makedirs("/var/www/lingpetshop", exist_ok=True)
os.chdir("/var/www/lingpetshop")

tar_data = base64.b64decode(b64_data.strip())
tar_bytes = io.BytesIO(tar_data)

with tarfile.open(fileobj=tar_bytes, mode="r:gz") as tar:
    tar.extractall(path="/var/www/lingpetshop")

print("📦 Installing dependencies...")
subprocess.run(["npm", "install"], check=True)

print("🔨 Building production store assets...")
subprocess.run(["npm", "run", "build"], check=True)

print("🚀 Starting PM2 service on port 3000...")
subprocess.run(["pm2", "delete", "all"], check=False)
subprocess.run(["pm2", "start", "npx tsx server.ts", "--name", "lingpetshop"], check=True)
subprocess.run(["pm2", "save"], check=True)

print("🎉 LING PETSHOP IS LIVE AT HTTPS://WWW.LINGPETSHOP.COM!")
